// Refresh-ahead in Node.js
const Redis = require('ioredis');
const redis = new Redis(process.env.REDIS_URL);

async function cacheWithRefresh(key, dbLoader, ttlSeconds) {
  const refreshSet = 'refresh:products';
  await redis.setex(key, ttlSeconds, JSON.stringify(await dbLoader()));
  const refreshAt = Date.now() + (ttlSeconds - 60) * 1000;
  await redis.zAdd(refreshSet, [{ score: refreshAt, value: key }]);
}

async function refreshAheadWorker() {
  const refreshSet = 'refresh:products';
  const now = Date.now();
  const keys = await redis.zRangeByScore(refreshSet, '-inf', now);
  for (const key of keys) {
    const product = await db('products').where('id', key.replace('product:', '')).first();
    if (product) {
      await redis.setex(key, 600, JSON.stringify(product));
      const nextRefresh = Date.now() + 8 * 60 * 1000;
      await redis.zAdd(refreshSet, [{ score: nextRefresh, value: key }]);
    }
  }
}

// Run every 30 seconds
setInterval(refreshAheadWorker, 30000);

// Refresh-ahead in C#
using StackExchange.Redis;
using System.Text.Json;

public class RefreshAheadService
{
    private readonly IDatabase _redis;
    private readonly AppDbContext _db;

    public RefreshAheadService(IConnectionMultiplexer redis, AppDbContext db)
    {
        _redis = redis.GetDatabase();
        _db = db;
    }

    public async Task CacheProductAsync(int productId)
    {
        var product = await _db.Products.FindAsync(productId);
        if (product is null) return;

        var json = JsonSerializer.Serialize(product);
        var key = $"product:{productId}";
        await _redis.StringSetAsync(key, json, TimeSpan.FromMinutes(10));

        var refreshAt = DateTimeOffset.UtcNow.AddMinutes(9).ToUnixTimeMilliseconds();
        await _redis.SortedSetAddAsync("refresh:products", key, refreshAt);
    }

    public async Task RefreshDueProductsAsync()
    {
        var now = DateTimeOffset.UtcNow.ToUnixTimeMilliseconds();
        var dueKeys = await _redis.SortedSetRangeByScoreAsync("refresh:products", double.NegativeInfinity, now);

        foreach (var key in dueKeys)
        {
            var id = int.Parse(key.ToString().Split(':')[1]);
            var product = await _db.Products.FindAsync(id);
            if (product is not null)
            {
                var json = JsonSerializer.Serialize(product);
                await _redis.StringSetAsync(key, json, TimeSpan.FromMinutes(10));
                var nextRefresh = DateTimeOffset.UtcNow.AddMinutes(9).ToUnixTimeMilliseconds();
                await _redis.SortedSetAddAsync("refresh:products", key, nextRefresh);
            }
        }
    }
}
